INSERT INTO Dep_CustSetting3rd (custid, bettype, sporttype, islive, apositiontaking, mpositiontaking, spositiontaking, playerdiscount, discount, adiscount, sdiscount, minbet, maxbet)
SELECT C.custid, S.bettype, S.sporttype, islive, apositiontaking, mpositiontaking, spositiontaking, playerdiscount, discount, adiscount, sdiscount, minbet, maxbet
FROM Dep_CustSetting3rd CS WITH (NOLOCK)
	INNER JOIN #Cust_Having180 C ON CS.custid = C.CustID AND CS.sporttype = 180
	CROSS JOIN #SportMissing S 
WHERE S.SportType <> 180 
	AND NOT EXISTS (SELECT 1 FROM Dep_CustSetting3rd CS1 WITH (NOLOCK) WHERE CS1.custid = CS.custid AND S.SportType = CS1.sporttype AND S.Bettype = CS1.bettype)
